const q = $input.first().json.query || {};
const type  = q.type  || 'queries';
const days  = parseInt(q.days  || '28');
const limit = parseInt(q.limit || '50');
const rowLimit = (type === 'opportunities') ? 200 : limit;

const end   = new Date();
const start = new Date();
start.setDate(end.getDate() - days);

const requestBody = {
  startDate:  start.toISOString().slice(0, 10),
  endDate:    end.toISOString().slice(0, 10),
  dimensions: [type === 'pages' ? 'page' : 'query'],
  rowLimit,
  orderBy: [{ fieldName: 'impressions', sortOrder: 'DESCENDING' }]
};

return [{ json: { requestBody, type, limit } }];

const prev  = $('Parse GSC Params').first().json;
const type  = prev.type;
const limit = parseInt(prev.limit || '50');
const SITE  = 'https://www.coberturapolicarbonato.com.br';
const rows  = $input.first().json.rows || [];

let result = rows.map(r => ({
  [type === 'pages' ? 'page' : 'query']: (r.keys?.[0] || '').replace(SITE, ''),
  impressions: r.impressions || 0,
  clicks:      r.clicks || 0,
  ctr:         ((r.ctr || 0) * 100).toFixed(2) + '%',
  position:    (r.position || 0).toFixed(1)
}));

if (type === 'opportunities') {
  result = result
    .filter(r => parseFloat(r.position) >= 8 && parseFloat(r.position) <= 20 && r.impressions >= 5)
    .sort((a, b) => b.impressions - a.impressions)
    .slice(0, 20);
} else {
  result = result.sort((a, b) => b.impressions - a.impressions).slice(0, limit);
}

// Retorna items individuais (n8n exige json = objeto, não array)
if (result.length === 0) return [{ json: { _empty: true } }];
return result.map(item => ({ json: item }));

const q = $input.first().json.query || {};
const type  = q.type  || 'overview';
const days  = parseInt(q.days  || '28');
const limit = parseInt(q.limit || '20');

let requestBody;
if (type === 'overview') {
  requestBody = {
    dateRanges: [{ startDate: days + 'daysAgo', endDate: 'yesterday' }],
    metrics: [
      { name: 'sessions' }, { name: 'activeUsers' }, { name: 'conversions' },
      { name: 'bounceRate' }, { name: 'averageSessionDuration' }
    ]
  };
} else if (type === 'acquisition') {
  requestBody = {
    dateRanges: [{ startDate: days + 'daysAgo', endDate: 'yesterday' }],
    dimensions: [{ name: 'sessionDefaultChannelGroup' }],
    metrics: [{ name: 'sessions' }, { name: 'conversions' }],
    orderBys: [{ metric: { metricName: 'sessions' }, desc: true }]
  };
} else if (type === 'toppages') {
  requestBody = {
    dateRanges: [{ startDate: days + 'daysAgo', endDate: 'yesterday' }],
    dimensions: [{ name: 'pagePath' }],
    metrics: [
      { name: 'sessions' }, { name: 'conversions' },
      { name: 'bounceRate' }, { name: 'averageSessionDuration' }
    ],
    orderBys: [{ metric: { metricName: 'sessions' }, desc: true }],
    limit
  };
} else if (type === 'realtime') {
  requestBody = {
    metrics: [{ name: 'activeUsers' }],
    dimensions: [{ name: 'city' }],
    limit: 10
  };
}

return [{ json: { requestBody, type, limit, isRealtime: type === 'realtime' } }];

const { type } = $('Parse GA4 Params').first().json;
const data = $input.first().json;

const mv = (row, i) => row?.metricValues?.[i]?.value ?? '0';
const dv = (row, i) => row?.dimensionValues?.[i]?.value ?? '';

if (type === 'overview') {
  const row = data.rows?.[0];
  return [{ json: {
    sessions:              parseInt(mv(row, 0)),
    activeUsers:           parseInt(mv(row, 1)),
    conversions:           parseInt(mv(row, 2)),
    bounceRate:            (parseFloat(mv(row, 3)) * 100).toFixed(1) + '%',
    avgSessionDurationSec: Math.round(parseFloat(mv(row, 4)))
  }}];
}

if (type === 'realtime') {
  return [{ json: {
    total:  parseInt(data.totals?.[0]?.metricValues?.[0]?.value || '0'),
    byCity: (data.rows || []).map(row => ({
      city:  dv(row, 0),
      users: parseInt(mv(row, 0))
    }))
  }}];
}

if (type === 'acquisition') {
  const rows = (data.rows || []).map(row => ({
    channel:     dv(row, 0),
    sessions:    parseInt(mv(row, 0)),
    conversions: parseInt(mv(row, 1))
  }));
  if (rows.length === 0) return [{ json: { _empty: true } }];
  return rows.map(r => ({ json: r }));
}

if (type === 'toppages') {
  const rows = (data.rows || []).map(row => ({
    page:        dv(row, 0),
    sessions:    parseInt(mv(row, 0)),
    conversions: parseInt(mv(row, 1)),
    bounceRate:  (parseFloat(mv(row, 2)) * 100).toFixed(1) + '%',
    avgDuration: Math.round(parseFloat(mv(row, 3))) + 's'
  }));
  if (rows.length === 0) return [{ json: { _empty: true } }];
  return rows.map(r => ({ json: r }));
}

return [{ json: data }];

