const q = $input.first().json.query || {};
const type  = q.type  || 'campaign';
const days  = parseInt(q.days  || '30');
const limit = parseInt(q.limit || '30');

let gaql;
if (type === 'campaign') {
  gaql = `SELECT campaign.name, campaign.status, metrics.impressions, metrics.clicks, metrics.cost_micros, metrics.conversions, metrics.ctr, metrics.average_cpc FROM campaign WHERE segments.date DURING LAST_${days}_DAYS ORDER BY metrics.cost_micros DESC`;
} else if (type === 'keywords') {
  gaql = `SELECT ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type, metrics.impressions, metrics.clicks, metrics.cost_micros, metrics.conversions, metrics.average_cpc FROM keyword_view WHERE segments.date DURING LAST_${days}_DAYS AND ad_group_criterion.status != 'REMOVED' ORDER BY metrics.cost_micros DESC LIMIT ${limit}`;
} else if (type === 'searchterms') {
  gaql = `SELECT search_term_view.search_term, metrics.impressions, metrics.clicks, metrics.cost_micros, metrics.conversions FROM search_term_view WHERE segments.date DURING LAST_${days}_DAYS ORDER BY metrics.impressions DESC LIMIT ${limit}`;
}

return [{ json: { gaql, type, limit } }];

const { type } = $('Parse Ads Params').first().json;
const results = $input.first().json.results || [];

let rows = [];
if (type === 'campaign') {
  rows = results.map(r => ({
    campaign:    r.campaign?.name || '',
    status:      r.campaign?.status || '',
    impressions: r.metrics?.impressions || 0,
    clicks:      r.metrics?.clicks || 0,
    costBRL:     ((r.metrics?.costMicros || 0) / 1e6).toFixed(2),
    conversions: (r.metrics?.conversions || 0).toFixed(1),
    ctr:         ((r.metrics?.ctr || 0) * 100).toFixed(2) + '%',
    avgCPC:      'R$' + ((r.metrics?.averageCpc || 0) / 1e6).toFixed(2)
  }));
} else if (type === 'keywords') {
  rows = results.map(r => ({
    keyword:      r.adGroupCriterion?.keyword?.text || '',
    matchType:    r.adGroupCriterion?.keyword?.matchType || '',
    impressions:  r.metrics?.impressions || 0,
    clicks:       r.metrics?.clicks || 0,
    costBRL:      ((r.metrics?.costMicros || 0) / 1e6).toFixed(2),
    conversions:  (r.metrics?.conversions || 0).toFixed(1),
    avgCPC:       'R$' + ((r.metrics?.averageCpc || 0) / 1e6).toFixed(2),
    qualityScore: r.metrics?.qualityScore || 'N/A'
  }));
} else if (type === 'searchterms') {
  rows = results.map(r => ({
    term:        r.searchTermView?.searchTerm || '',
    impressions: r.metrics?.impressions || 0,
    clicks:      r.metrics?.clicks || 0,
    costBRL:     ((r.metrics?.costMicros || 0) / 1e6).toFixed(2),
    conversions: (r.metrics?.conversions || 0).toFixed(1)
  }));
}

if (rows.length === 0) return [{ json: { _empty: true } }];
return rows.map(r => ({ json: r }));

